1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's canonical region ('locality'). The postcode is preferred: a
9	 * postcode falling in a known region's range ({@code NSW 2000-2099}, {@code VIC
10	 * 3000-3099}, {@code QLD 4000-4099}) determines the region directly. Only when the
11	 * postcode is absent or in no known range does derivation fall back to the fixed
12	 * city-to-region table. A city (or postcode) that resolves to no region derives the
13	 * locality {@code "UNKNOWN"}.
14	 */
15	public final class Localities {
16	
17	    /** Fixed city -> canonical region table. */
18	    private static final Map<String, String> CITY_REGION = Map.of(
19	            "Sydney", "NSW",
20	            "Melbourne", "VIC",
21	            "Brisbane", "QLD");
22	
23	    /** Region -> inclusive 4-digit postcode range {low, high}. */
24	    private static final Map<String, int[]> REGION_RANGE = Map.of(
25	            "NSW", new int[] {2000, 2099},
26	            "VIC", new int[] {3000, 3099},
27	            "QLD", new int[] {4000, 4099});
28	
29	    /** Fixed region -> IANA timezone table. */
30	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
31	            "NSW", "Australia/Sydney",
32	            "VIC", "Australia/Melbourne",
33	            "QLD", "Australia/Brisbane");
34	
35	    /** The locality returned when neither postcode nor city resolves to a region. */
36	    public static final String UNKNOWN = "UNKNOWN";
37	
38	    private Localities() {
39	    }
40	
41	    /**
42	     * Derives the owner's locality from its {@code memberId} identity
43	     * ({@code '<REGION><FY><HASH8><CHK>'}), whose leading REGION is the canonical region: the locality
44	     * is the leading run of letters, which stops at the first digit of the FY segment. Owners with no
45	     * {@code memberId} yet (e.g. seed data) fall back to deriving the region directly from postcode
46	     * and city.
47	     *
48	     * @param owner the owner (must not be {@code null}).
49	     * @return the canonical region for the owner, or {@code "UNKNOWN"} when none resolves.
50	     */
51	    public static String localityFor(Owner owner) {
52	        String memberId = owner.getMemberId();
53	        if (memberId != null) {
54	            int i = 0;
55	            while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
56	                i++;
57	            }
58	            if (i > 0) {
59	                return memberId.substring(0, i);
60	            }
61	        }
62	        return localityFor(owner.getCity(), owner.getPostcode());
63	    }
64	
65	    /**
66	     * Derives the owner's IANA timezone name from its locality/region via the fixed
67	     * region-to-timezone table ({@code NSW -> Australia/Sydney}, {@code VIC ->
68	     * Australia/Melbourne}, {@code QLD -> Australia/Brisbane}).
69	     *
70	     * @param owner the owner (must not be {@code null}).
71	     * @return the IANA timezone name, or {@code null} when the region is {@code "UNKNOWN"}
72	     *         (or otherwise not in the table).
73	     */
74	    public static String timezoneFor(Owner owner) {
75	        return REGION_TIMEZONE.get(localityFor(owner));
76	    }
77	
78	    /**
79	     * Derives the region from the city alone. Equivalent to {@link #localityFor(String,
80	     * String)} with a {@code null} postcode.
81	     *
82	     * @param city the owner's city (may be {@code null}).
83	     * @return the canonical region for {@code city}, or {@code "UNKNOWN"} when the
84	     *         city is {@code null} or not in the fixed table.
85	     */
86	    public static String localityFor(String city) {
87	        return localityFor(city, null);
88	    }
89	
90	    /**
91	     * Derives the region, preferring the postcode. The postcode is consulted first: if
92	     * it falls in a known region's range, that region is returned. Otherwise (postcode
93	     * absent, malformed, or out of every range) derivation falls back to the
94	     * city-to-region table.
95	     *
96	     * @param city     the owner's city (may be {@code null}).
97	     * @param postcode the owner's postcode (may be {@code null}).
98	     * @return the canonical region, or {@code "UNKNOWN"} when neither resolves.
99	     */
100	    public static String localityFor(String city, String postcode) {
101	        String byPostcode = regionForPostcode(postcode);
102	        if (byPostcode != null) {
103	            return byPostcode;
104	        }
105	        return city == null ? UNKNOWN : CITY_REGION.getOrDefault(city, UNKNOWN);
106	    }
107	
108	    /**
109	     * @return the region whose range contains {@code postcode}, or {@code null} when
110	     *         the postcode is {@code null}, not a 4-digit number, or in no known range.
111	     */
112	    private static String regionForPostcode(String postcode) {
113	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
114	            return null;
115	        }
116	        int value = Integer.parseInt(postcode);
117	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
118	            int[] range = entry.getValue();
119	            if (value >= range[0] && value <= range[1]) {
120	                return entry.getKey();
121	            }
122	        }
123	        return null;
124	    }
125	}
