1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.util.OwnerIdentities;
10	
11	/**
12	 * Assigns the unified {@code memberId} to the freshly built {@link Owner} before it is saved.
13	 *
14	 * <p>The id is formatted {@code '<REGION><FY><HASH8><CHK>'} (no separators): REGION is the region
15	 * code derived from the owner's postcode (falling back to city — see
16	 * {@link org.springframework.samples.petclinic.util.Localities}), FY the two-digit fiscal year of
17	 * the owner's {@code registrationDate}, HASH8 the first 8 upper-case hex characters of SHA-256 over
18	 * {@code normalizedTelephone + lastName}, and CHK a single Luhn check digit over the decimal digits
19	 * of {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSW261A2B3C4D5'}). It is a pure function of the
20	 * owner's region, fiscal year and identity and does not depend on other owners.
21	 *
22	 * <p>The computed id can nonetheless collide with an existing owner's {@code memberId}. When it
23	 * does, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that makes the id unique
24	 * (e.g. {@code 'NSW261A2B3C4D5-2'}, then {@code '-3'}, …), and the de-duplicated id is stored.
25	 *
26	 * <p>Runs before {@link SaveOwner} so the new owner is not yet persisted and cannot collide with
27	 * itself.
28	 */
29	public class AssignMemberId {
30	
31	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
32	        String base = OwnerIdentities.memberId(owner);
33	        Set<String> existing = new HashSet<>();
34	        for (Owner other : ownerRepository.findAll()) {
35	            if (owner.getId() != null && owner.getId().equals(other.getId())) {
36	                continue; // never collide with self
37	            }
38	            if (other.getMemberId() != null) {
39	                existing.add(other.getMemberId());
40	            }
41	        }
42	        String memberId = base;
43	        for (int n = 2; existing.contains(memberId); n++) {
44	            memberId = base + "-" + n;
45	        }
46	        owner.setMemberId(memberId);
47	    }
48	}
